// Reference food database bundled with the app (offline, no network): 6,494 foods per 100 g from the
// TempoLife food dataset (tempolife.app, CC-BY-4.0), itself mostly USDA FoodData Central SR Legacy
// (public domain). Generated by scripts/build-fooddb.py; see data/README.md for attribution.
import db from '../data/fooddb.json';
import type { Nutrients } from './model.ts';

export const FOODDB_ATTRIBUTION = 'Food nutrition data from TempoLife (tempolife.app), CC-BY-4.0, and USDA FoodData Central.';

type Row = [string, number, number, number, number, number | null, number | null, number | null];

export interface DbFood {
  ref: string;
  name: string;
  n: Nutrients;
}

/** Stable short id from the food name (FNV-1a), so diary entries and favorites survive regeneration. */
export function dbRef(name: string): string {
  let h = 0x811c9dc5;
  for (let i = 0; i < name.length; i++) {
    h ^= name.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return `u:${(h >>> 0).toString(36)}`;
}

let cache: DbFood[] | null = null;
export function dbFoods(): DbFood[] {
  if (cache) return cache;
  cache = (db.rows as Row[]).map(([name, kcal, protein_g, carbs_g, fat_g, fiber_g, sugar_g, sodium_mg]) => {
    const n: Nutrients = { kcal, protein_g, carbs_g, fat_g };
    if (fiber_g !== null) n.fiber_g = fiber_g;
    if (sugar_g !== null) n.sugar_g = sugar_g;
    if (sodium_mg !== null) n.sodium_mg = sodium_mg;
    return { ref: dbRef(name), name, n };
  });
  return cache;
}
